drop index public."uq_fact_decision_effective";
CREATE UNIQUE INDEX uq_fact_decision_effective ON public.fact_decisions USING btree (project_id, subject_key, fact_type) WHERE ((superseded_by IS NULL) AND (fact_type IN ('utility_id', 'external_org', 'external_org_contact', 'utility_type', 'utility_subtype', 'utility_function', 'operational_status', 'size', 'material', 'oh_ug', 'row_placement', 'orientation', 'baseline', 'station_from', 'station_to', 'offset_from', 'offset_to', 'sue_level', 'conflict_description', 'resolution_strategy', 'notes', 'alignment', 'location_start', 'location_end', 'offset_side', 'potential_conflict', 'data_source', 'marked_resolution', 'committed_date', 'action_due_date', 'need_date', 'closure_result')));
